<div class="d-flex flex-md-column gap-1 justify-content-end">
    <button type="button" class="btn btn-sm btn-light" data-row-action="up" title="Move up"><i class="fas fa-arrow-up"></i></button>
    <button type="button" class="btn btn-sm btn-light" data-row-action="down" title="Move down"><i class="fas fa-arrow-down"></i></button>
    <button type="button" class="btn btn-sm btn-light text-danger" data-row-action="remove" title="Remove"><i class="fas fa-trash"></i></button>
</div>
